// ===== LOGIN - Popula ambiente =====

insomnia.test("[STATUS] Deve retornar 200 OK", () => {
    insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test("[BODY] Deve retornar o customerId do usuário", () => {
    const data = insomnia.response.json();
    insomnia.expect(data).to.have.property('id');
    insomnia.expect(data.id).to.be.a('number');
    // Salva customer_id no ambiente
    insomnia.environment.set('customer_id', String(data.id));
    insomnia.environment.set('_logged_in', 'true');
});

insomnia.test("[BODY] Deve retornar firstName e lastName", () => {
    const data = insomnia.response.json();
    insomnia.expect(data).to.have.property('firstName');
    insomnia.expect(data).to.have.property('lastName');
});

insomnia.test("[PERFORMANCE] Tempo de resposta deve ser menor que 5s", () => {
    insomnia.expect(insomnia.response.responseTime).to.be.below(5000);
});

// ===== SETUP: Popula account_id e to_account_id =====

insomnia.test("[STATUS] Deve retornar 200 OK", () => {
    insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test("[SETUP] Salva account_id (1ª conta) no ambiente", () => {
    const data = insomnia.response.json();
    insomnia.expect(data).to.be.an('array');
    insomnia.expect(data.length).to.be.greaterThan(0);
    insomnia.environment.set('account_id', String(data[0].id));
});

insomnia.test("[SETUP] Salva to_account_id (2ª conta ou mesma se só há uma)", () => {
    const data = insomnia.response.json();
    if (data.length >= 2) {
        insomnia.environment.set('to_account_id', String(data[1].id));
    } else {
        insomnia.environment.set('to_account_id', String(data[0].id));
    }
});

insomnia.test("[PERFORMANCE] Tempo de resposta deve ser menor que 5s", () => {
    insomnia.expect(insomnia.response.responseTime).to.be.below(5000);
});

// ===== ACCOUNTS OVERVIEW - POSITIVO =====

insomnia.test("[STATUS] Deve retornar 200 OK", () => {
    insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test("[HEADERS] Content-Type deve conter application/json", () => {
    const ct = insomnia.response.headers.find(h => h.key.toLowerCase() === 'content-type');
    insomnia.expect(ct.value).to.include('application/json');
});

insomnia.test("[BODY] Resposta deve ser um array não-vazio", () => {
    const data = insomnia.response.json();
    insomnia.expect(data).to.be.an('array');
    insomnia.expect(data.length).to.be.greaterThan(0);
});

insomnia.test("[BODY] Cada conta deve ter id, customerId, type e balance", () => {
    const data = insomnia.response.json();
    data.forEach(account => {
        insomnia.expect(account).to.have.property('id');
        insomnia.expect(account).to.have.property('customerId');
        insomnia.expect(account).to.have.property('type');
        insomnia.expect(account).to.have.property('balance');
    });
});

insomnia.test("[PERFORMANCE] Tempo de resposta deve ser menor que 5s", () => {
    insomnia.expect(insomnia.response.responseTime).to.be.below(5000);
});

// ===== ACCOUNTS OVERVIEW - NEGATIVO =====
// ParaBank retorna 400 para cliente inexistente.

insomnia.test("[STATUS] Deve retornar erro (4xx ou 5xx) para cliente inexistente", () => {
    insomnia.expect(insomnia.response.code).to.be.greaterThan(399);
});

insomnia.test("[BUG] API retorna 400 ao invés de 404 para cliente inexistente", () => {
    insomnia.expect(insomnia.response.code).to.eql(400);
});

insomnia.test("[EVIDÊNCIA] Deveria retornar 404 Not Found (comportamento correto)", () => {
    // FALHA INTENCIONAL - documenta que o ideal seria 404
    insomnia.expect(insomnia.response.code).to.eql(404);
});

insomnia.test("[SEGURANÇA] Resposta não deve conter dados de contas bancárias", () => {
    const body = insomnia.response.text();
